import ipaddress
import socket
import urllib.parse

parsed = urllib.parse.urlsplit(url or "")
if parsed.scheme not in ("http", "https"):
    raise ValueError("only http and https are permitted, not %r" % parsed.scheme)
host = parsed.hostname
if not host:
    raise ValueError("no host in url")

if allowlist and host.lower() not in [h.lower() for h in allowlist]:
    raise PermissionError("%s is not on this integration's egress allowlist" % host)

port = parsed.port or (443 if parsed.scheme == "https" else 80)
try:
    infos = socket.getaddrinfo(host, port, proto=socket.IPPROTO_TCP)
except socket.gaierror as error:
    raise ValueError("cannot resolve %s: %s" % (host, error))

addresses = {info[4][0] for info in infos}
for raw in addresses:
    address = ipaddress.ip_address(raw)
    if (address.is_private or address.is_loopback or address.is_link_local
            or address.is_reserved or address.is_multicast
            or address.is_unspecified):
        raise PermissionError("%s resolves to a non-routable address (%s)" % (host, raw))
    # The cloud instance metadata service, by address, on every provider.
    if raw in ("169.254.169.254", "fd00:ec2::254", "100.100.100.200"):
        raise PermissionError("%s resolves to an instance metadata endpoint" % host)

return {"host": host, "port": port, "addresses": sorted(addresses), "scheme": parsed.scheme}

from soar.normalize.engine import read_path
from soar.playbooks.template import encode_for, render

import httpx
import json
import time
import urllib.parse as parse_url

login = scheme.get("login") or {}
if not login.get("path"):
    raise ValueError("session auth needs a login path")

# The sign-in goes to the host the commands go to, which is the host the
# operator configured and the allowlist was built from. A login path that
# could name its own host would be a way to post credentials elsewhere.
origin = parse_url.urlsplit(url)
login_url = parse_url.urlunsplit(
    (origin.scheme, origin.netloc, login["path"], "", ""))
check_destination(login_url, allowlist)

# One session per host and user, reused until it is nearly stale. Signing
# in once per command would make every playbook step two round trips, and
# some of these products count sign-ins against a limit.
cache = getattr(open_vendor_session, "cache", None)
if cache is None:
    cache = {}
    open_vendor_session.cache = cache

roles = scheme.get("roles") or []
identity = encode_for(lease.get(roles[0]), "header") if roles else ""
# The selector is part of the key: two integrations can share a host
# and a user and still want different things out of the sign-in.
key = (login_url, identity, login.get("cookie") or login.get("token"))
cached = cache.get(key)
if cached and cached[1] > time.time():
    return dict(cached[0])

sent = None
form = None
if login.get("body") is not None:
    sent = json.loads(render(json.dumps(login["body"]), context,
                             position="json"))
if login.get("form") is not None:
    form = {name: render(str(template), context, position="header")
            for name, template in login["form"].items()}

with httpx.Client(timeout=timeout_ms / 1000.0, follow_redirects=False) as client:
    response = client.request(login.get("method", "POST"), login_url,
                              json=sent, data=form)

if response.status_code not in login.get("success_codes", [200, 201, 204]):
    raise RuntimeError(json.dumps({
        "error_class": "AUTH",
        "status": response.status_code,
        "message": "the vendor refused the sign-in",
    }))

produced = {}
if login.get("cookie"):
    value = response.cookies.get(login["cookie"])
    if not value:
        raise RuntimeError(json.dumps({
            "error_class": "AUTH", "status": response.status_code,
            "message": "sign-in succeeded but set no %s cookie"
                       % login["cookie"],
        }))
    produced["Cookie"] = "%s=%s" % (login["cookie"], value)
elif login.get("token"):
    try:
        payload = response.json()
    except ValueError:
        payload = {}
    token = read_path(payload, login["token"])
    if not token:
        raise RuntimeError(json.dumps({
            "error_class": "AUTH", "status": response.status_code,
            "message": "sign-in returned nothing at %s" % login["token"],
        }))
    produced[login.get("header", "Authorization")] = (
        login.get("prefix", "") + str(token))
else:
    raise ValueError("session auth needs either a cookie or a token path")

# Well short of any real expiry: a session that dies mid-playbook fails a
# containment step, and signing in again is cheap.
cache[key] = (dict(produced), time.time() + int(login.get("ttl_s", 900)))
return produced

from soar.normalize.engine import read_path
from soar.platform.errors import classify_http_status
from soar.playbooks.template import render

import httpx
import json

import urllib.parse as parse_url

# The scopes a command template may read. "integration" is what makes one
# command definition serve every deployment of a product: the connector
# writes {{ integration.config.workspace_id }} and each client fills it in
# on their own integration row.
context = {
    "inputs": inputs or {},
    "credentials": lease or {},
    "integration": {"config": implementation.get("config") or {}},
}

url = render(fill_settings(implementation["url"], context["integration"]["config"]),
             context, position="url")

# A connector that hard-codes its vendor host still has to reach the cloud
# this client is actually on - a Falcon region, a tenant-specific hostname,
# an on-premise appliance. Swap the origin, keep the path, so the override
# works whether or not the manifest was written to expect one.
configured = str((implementation.get("config") or {}).get("base_url") or "").strip()
if configured:
    want = parse_url.urlsplit(configured)
    have = parse_url.urlsplit(url)
    if want.netloc and want.netloc != have.netloc:
        url = parse_url.urlunsplit((want.scheme or have.scheme, want.netloc,
                                    have.path, have.query, ""))
headers = {}
for name, template in (implementation.get("headers") or {}).items():
    headers[name] = render(template, context, position="header")

url = apply_auth(implementation.get("auth_scheme"), lease, context, headers,
                 url, allowlist, timeout_ms)

# Screened after the auth scheme has had its say, because a scheme may put
# the key in the query string and that is still the request that goes out.
destination = check_destination(url, allowlist)

def render_body(value):
    # Rendered structurally, not by stringifying the whole body and
    # substituting into the text. A template that IS the entire value -
    # "composite_ids": "{{ inputs.alert_ids }}" - has to become the list,
    # and the text approach produced "[\"a\", \"b\"]" inside the quotes
    # that were already there, which is not JSON at all.
    if isinstance(value, dict):
        return {k: render_body(v) for k, v in value.items()}
    if isinstance(value, list):
        return [render_body(v) for v in value]
    if not isinstance(value, str):
        return value

    rendered = render(value, context, position="json")
    stripped = value.strip()
    whole = (stripped.startswith("{{") and stripped.endswith("}}")
             and stripped.count("{{") == 1)
    if whole and rendered[:1] in ("[", "{"):
        # Only containers are lifted out of their quotes. A scalar is
        # already correct as a string, and reading it back as JSON would
        # turn a hostname of "123" into the number 123.
        try:
            return json.loads(rendered)
        except ValueError:
            return rendered
    # Back through JSON so the escaping encode_for applied is undone.
    return json.loads(chr(34) + rendered + chr(34))

body = None
if implementation.get("body") is not None:
    body = render_body(implementation["body"])

# Redirects are followed manually so each hop is screened again. Letting the
# client follow them is how an allowlisted host becomes a redirect to 169.254.
with httpx.Client(timeout=timeout_ms / 1000.0, follow_redirects=False) as client:
    current = url
    for hop in range(3):
        response = client.request(
            implementation["method"], current, headers=headers, json=body
        )
        if response.status_code not in (301, 302, 303, 307, 308):
            break
        current = str(response.next_request.url) if response.next_request else current
        check_destination(current, allowlist)
    else:
        raise ValueError("too many redirects")

try:
    payload = response.json()
except ValueError:
    payload = {"text": response.text[:65536]}

result = {"status": response.status_code, "body": payload}
for name, path in (implementation.get("extract") or {}).items():
    result[name] = read_path(payload, path)

if response.status_code not in implementation.get("success_codes", [200]):
    raise RuntimeError(json.dumps({
        "error_class": classify_http_status(response.status_code),
        "status": response.status_code,
        "host": destination["host"],
    }))
return result
